/** Safari may synthesize mouse events after touch, including when menus change. */
export class CursorInput {
 private touchAt=-Infinity;
 private mouse=false;
 touch(now:number){this.touchAt=now;this.mouse=false;}
 accepts(event:{pointerType?:string;type?:string;sourceCapabilities?:{firesTouchEvents?:boolean}},now:number,fine:boolean){
  if(event.pointerType==='touch'||event.pointerType==='pen'||event.sourceCapabilities?.firesTouchEvents){this.touch(now);return false;}
  if(!fine||now-this.touchAt<900){this.mouse=false;return false;}
  // Hover generated by revealing a menu is not evidence of an attached mouse.
  if(event.pointerType==='mouse'&&(event.type==='pointermove'||event.type==='pointerdown'))this.mouse=true;
  return this.mouse;
 }
}
